    kind: "photo",
    title,
    imageUrl: `${TODAY_LOCAL_VISUAL_PREFIX}${fileName}`,
    imagePageUrl: `${TODAY_LOCAL_VISUAL_PREFIX}${fileName}`,
    license: "Aletheia curated",
