function orderedTodayVisualAssets(
  theme: string,
  mood: TodayVisualMood,
  dayNumber: number,
  overrideTitles?: string[],
  attempt: number = 0
) {
  const visualTheme = resolveTodayVisualTheme(theme);
  const keyedAssets = TODAY_VISUAL_LIBRARY[visualTheme];
  if (!keyedAssets || keyedAssets.length === 0) {
    return null;
  }

  const preferredTitles =
    overrideTitles ??
    TODAY_THEME_MOOD_PRIORITIES[visualTheme]?.[mood] ??
    TODAY_THEME_VISUAL_PRIORITIES[visualTheme] ??
    [];
  const prioritizedAssets = preferredTitles
    .map((title) => keyedAssets.find((asset) => asset.title === title))
    .filter((asset): asset is TodayVisualAsset => Boolean(asset));
  const remainingAssets = keyedAssets.filter((asset) => !preferredTitles.includes(asset.title));
  const orderedAssets = [...prioritizedAssets, ...remainingAssets];
  if (orderedAssets.length === 0) {
    return null;
  }

  const baseIndex = stableHash(`${theme}:${visualTheme}:${mood}:${dayNumber}:today-visual`) % orderedAssets.length;
  const index = (baseIndex + Math.max(0, attempt)) % orderedAssets.length;
  return orderedAssets[index];
}

const TODAY_GENERIC_VISUALS: TodayVisualIllustration[] = [
  { kind: "illustration", title: "Quiet field", variant: "field" },
  { kind: "illustration", title: "Stillness", variant: "stillness" },
  { kind: "illustration", title: "Soft path", variant: "path" },
];

function selectTodayVisualAsset({
  theme,
  dayNumber,
  mood,
  hour,
  month,
  dayOfWeek,
  attempt = 0,
  localOnly = false,
}: {
  theme: string;
  dayNumber: number;
  mood: TodayVisualMood;
  hour: number | null;
  month: number | null;
  dayOfWeek: number | null;
  attempt?: number;
  localOnly?: boolean;
}): TodayVisualAsset {
  const visualTheme = resolveTodayVisualTheme(theme);
  const localAssets = localTodayVisualsForTheme(visualTheme);
  if (localOnly) {
    const localIndex = stableHash(`${visualTheme}:${mood}:${dayNumber}:today-local`) % localAssets.length;
    return localAssets[(localIndex + Math.max(0, attempt)) % localAssets.length];
  }

  const isMorningSunriseTheme = (visualTheme === THEME_KEYS.STEWARDSHIP || visualTheme === THEME_KEYS.GENEROSITY) && hour !== null && hour >= 5 && hour < 11;
  const isWinterTheme = visualTheme === THEME_KEYS.PROVISION_AND_ANXIETY && month !== null && [12, 1, 2].includes(month);
  const isWeekendTheme = (visualTheme === THEME_KEYS.COUNSEL || visualTheme === DEFAULT_TODAY_VISUAL_THEME) && dayOfWeek !== null && (dayOfWeek === 0 || dayOfWeek === 6);
  const effectiveMood = isMorningSunriseTheme
    ? "warm"
    : isWinterTheme
      ? "cool"
      : isWeekendTheme
        ? "contemplative"
        : mood;
  const humanAccent = shouldUseHumanAccent({
    theme: visualTheme,
    mood: effectiveMood,
    hour,
    month,
    dayOfWeek,
    dayNumber,
  });
  const landscapeTitles =
    isMorningSunriseTheme
      ? TODAY_THEME_TIME_PRIORITIES[visualTheme]?.morning
      : isWinterTheme
        ? TODAY_THEME_TIME_PRIORITIES[visualTheme]?.winter
        : isWeekendTheme
          ? TODAY_THEME_TIME_PRIORITIES[visualTheme]?.weekend
          : undefined;
  const humanTitles = humanAccent ? TODAY_THEME_HUMAN_PRIORITIES[visualTheme]?.[effectiveMood] ?? TODAY_THEME_HUMAN_PRIORITIES[visualTheme]?.warm : undefined;
  const orderedAssets = orderedTodayVisualAssets(visualTheme, effectiveMood, dayNumber, humanTitles ?? landscapeTitles, attempt);
  if (orderedAssets) {
    return orderedAssets;
  }

  if (humanAccent) {
    const fallbackLandscape = orderedTodayVisualAssets(visualTheme, effectiveMood, dayNumber, landscapeTitles, attempt);
    if (fallbackLandscape) {
      return fallbackLandscape;
    }
  }

  const fallbackIndex = stableHash(`${visualTheme}:${effectiveMood}:${dayNumber}:today-generic`) % TODAY_GENERIC_VISUALS.length;
  if (localAssets.length > 0) {
    const localIndex = stableHash(`${visualTheme}:${effectiveMood}:${dayNumber}:today-local`) % localAssets.length;
    return localAssets[(localIndex + Math.max(0, attempt)) % localAssets.length];
  }

  return TODAY_GENERIC_VISUALS[fallbackIndex];
}

function resolveTodayVisualPlacement({
  theme,
  mood,
  hour,
  month,
  dayOfWeek,
  fallbackLevel,
}: {
  theme: string;
  mood: TodayVisualMood;
  hour: number | null;
  month: number | null;
  dayOfWeek: number | null;
  fallbackLevel: TodayVisualFallbackLevel;
}): TodayVisualPlacement {
  const isMorning = hour !== null && hour >= 5 && hour < 11;
  const isAfternoon = hour !== null && hour >= 11 && hour < 17;
  const isEvening = hour !== null && hour >= 17;
  const isWinter = month !== null && [12, 1, 2].includes(month);
  const isWeekend = dayOfWeek !== null && (dayOfWeek === 0 || dayOfWeek === 6);
  const isMorningStewardshipTheme = theme === THEME_KEYS.STEWARDSHIP && isMorning;
  const isMorningGenerosityTheme = theme === THEME_KEYS.GENEROSITY && isMorning;
  const isWinterTheme = theme === THEME_KEYS.PROVISION_AND_ANXIETY && isWinter;
  const isWeekendTheme = (theme === THEME_KEYS.COUNSEL || theme === DEFAULT_TODAY_VISUAL_THEME) && isWeekend;
  const isWarmMood = mood === "warm";
  const isQuietMood = mood === "contemplative";

  let wrapperClassName = "mt-4 w-full self-stretch md:mt-0 md:self-start md:justify-self-end";
  let imageClassName = "object-cover";
  let objectPosition = "center 36%";
  let overlayGradient = "linear-gradient(180deg, rgba(8, 11, 10, 0.00) 0%, rgba(8, 11, 10, 0.02) 48%, rgba(8, 11, 10, 0.14) 100%)";
  let figureMinHeight = "168px";
  let figureWidth = "100%";
  let figureOpacity = 1;

  if (fallbackLevel === "illustration") {
    wrapperClassName = "mt-3 w-full self-stretch md:mt-0 md:self-start md:justify-self-end";
    imageClassName = "object-contain";
    objectPosition = "center 44%";
    overlayGradient = "linear-gradient(180deg, rgba(8, 11, 10, 0.00) 0%, rgba(8, 11, 10, 0.02) 52%, rgba(8, 11, 10, 0.12) 100%)";
    figureMinHeight = "164px";
    figureWidth = "100%";
    figureOpacity = 0.98;
  } else if (fallbackLevel === "fallback") {
    wrapperClassName = "mt-3 w-full self-stretch md:mt-0 md:self-start md:justify-self-end";
    imageClassName = "object-contain";
    objectPosition = "center 46%";
    overlayGradient = "linear-gradient(180deg, rgba(8, 11, 10, 0.00) 0%, rgba(8, 11, 10, 0.03) 54%, rgba(8, 11, 10, 0.10) 100%)";
    figureMinHeight = "162px";
    figureWidth = "100%";
    figureOpacity = 0.94;
  }

  if (isMorningStewardshipTheme) {
    wrapperClassName = wrapperClassName.replace("mt-4", "mt-5");
    objectPosition = "center 30%";
    overlayGradient = "linear-gradient(180deg, rgba(8, 11, 10, 0.00) 0%, rgba(8, 11, 10, 0.03) 42%, rgba(8, 11, 10, 0.16) 100%)";
  } else if (isMorningGenerosityTheme) {
    wrapperClassName = wrapperClassName.replace("mt-4", "mt-5");
    objectPosition = "center 40%";
    overlayGradient = "linear-gradient(180deg, rgba(8, 11, 10, 0.00) 0%, rgba(8, 11, 10, 0.03) 44%, rgba(8, 11, 10, 0.13) 100%)";
  } else if (isWinterTheme) {
    wrapperClassName = wrapperClassName.replace("mt-4", "mt-5");
    objectPosition = "center 48%";
    overlayGradient = "linear-gradient(180deg, rgba(8, 11, 10, 0.00) 0%, rgba(8, 11, 10, 0.04) 44%, rgba(8, 11, 10, 0.18) 100%)";
  } else if (isWeekendTheme) {
    wrapperClassName = wrapperClassName.replace("mt-4", "mt-5");
    objectPosition = "center 40%";
    overlayGradient = "linear-gradient(180deg, rgba(8, 11, 10, 0.00) 0%, rgba(8, 11, 10, 0.03) 46%, rgba(8, 11, 10, 0.14) 100%)";
  } else if (isAfternoon) {
    objectPosition = "center 38%";
  } else if (isEvening || isQuietMood) {
    objectPosition = "center 44%";
  } else if (isWarmMood) {
    objectPosition = "center 34%";
  }

  return {
    wrapperClassName,
    imageClassName,
    objectPosition,
    overlayGradient,
    figureMinHeight,
    figureWidth,
    figureOpacity,
  };
}

