function personalizedCarryPhraseFor(key: PersonalizedCarryPhraseKey, language: LanguageCode) {
  return personalizedCarryPhrases[key][language] ?? personalizedCarryPhrases[key].en ?? "";
}

function personalizedCarryPhrase({
  language,
  manualContext,
  focusIntentions,
  activeDecision,
}: {
  language: LanguageCode;
  manualContext: ManualContextProfile;
  focusIntentions: string[];
  activeDecision: WisdomDecision | null;
}) {
  const signals = manualContextCounselSignals(manualContext).join(" ").toLowerCase();
  if (signals.includes("financial pressure")) {
    return personalizedCarryPhraseFor("financialPressure", language);
  }
  if (signals.includes("burnout")) {
    return personalizedCarryPhraseFor("burnout", language);
  }
  if (signals.includes("isolation")) {
    return personalizedCarryPhraseFor("isolation", language);
  }
  if (signals.includes("urgency")) {
    return personalizedCarryPhraseFor("urgency", language);
  }
  if (signals.includes("values")) {
    return personalizedCarryPhraseFor("values", language);
  }
  if (signals.includes("future-state")) {
    return personalizedCarryPhraseFor("futureState", language);
  }

  if (activeDecision) {
    return personalizedCarryPhraseFor("activeDecision", language);
  }

  const focusKey = focusIntentions.find((value): value is FocusIntentionKey =>
    focusIntentionLibrary.includes(value as FocusIntentionKey)
  );
  return focusKey ? personalizedCarryPhraseFor(focusKey, language) : "";
}

function localTodayKey() {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function storedCarryToday(preferences: UserPreferences): CarryToday | null {
  if (typeof window === "undefined") {
    return null;
  }
  try {
    const parsed = JSON.parse(window.localStorage.getItem(CARRY_TODAY_STORAGE_KEY) || "null") as CarryToday | null;
    return parsed?.date === localTodayKey() &&
      parsed.phrase &&
      parsed.language === preferences.language &&
      parsed.bibleTranslation === preferences.bibleTranslation
      ? parsed
      : null;
  } catch {
    return null;
  }
}

function currentWeekKey(date = new Date()) {
  const start = new Date(date);
  start.setHours(0, 0, 0, 0);
  start.setDate(start.getDate() - ((start.getDay() + 6) % 7));
  return localTodayKeyFromDate(start);
}

function localTodayKeyFromDate(date: Date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function storedScriptureMemory(preferences: UserPreferences): ScriptureMemory | null {
  if (typeof window === "undefined") {
    return null;
  }
  try {
    const parsed = JSON.parse(window.localStorage.getItem(SCRIPTURE_MEMORY_STORAGE_KEY) || "null") as ScriptureMemory | null;
    if (!parsed?.scripture || parsed.weekKey !== currentWeekKey()) {
      return null;
    }

    const canonical = canonicalScriptureReference(parsed.scripture);
    const sourceEntry = baseWisdomEntries.find((entry) => canonicalScriptureReference(entry.scripture) === canonical);
    if (!sourceEntry) {
      return parsed;
    }

    const localizedPrinciple = localizedWisdomEntry(sourceEntry, preferences).principle;
    if (!localizedPrinciple || parsed.principle === localizedPrinciple) {
      return parsed;
    }

    const migrated: ScriptureMemory = {
      ...parsed,
      principle: localizedPrinciple,
    };

    try {
      window.localStorage.setItem(SCRIPTURE_MEMORY_STORAGE_KEY, JSON.stringify(migrated));
    } catch {
      // Return migrated memory for this session even if persistence is unavailable.
    }

    return migrated;
  } catch {
    return null;
  }
}

function buildDecisionBlessing(decision: WisdomDecision, ts: (key: string, fallback?: string) => string) {
  return [
    ts('labels.decisionBlessingOpening'),
    ts('labels.decisionBlessingClarity'),
    ts('labels.decisionBlessingDecision').replace("{decision}", decision.title),
    ts('labels.decisionBlessingEnding'),
  ].join("\n\n");
}

function companionCardFromDaily({
  daily,
  entry,
  pattern,
  language,
  manualContext,
  focusIntentions,
  activeDecision,
}: {
  daily: ReturnType<typeof localizedDailyWisdom>;
  entry: Pick<WisdomEntryData, "questions"> & { theme: string };
  pattern: string;
  language: LanguageCode;
  manualContext: ManualContextProfile;
  focusIntentions: string[];
  activeDecision: WisdomDecision | null;
}): TodayCompanionCard {
  const theme = daily.theme || entry.theme;
  const companionTemplate = getCompanionTemplate(resolveGenerationLanguage(language));
  const shortQuestion = entry.questions[0] || companionTemplate.reflectionQuestion;
  const personalizedPhrase = personalizedCarryPhrase({ language, manualContext, focusIntentions, activeDecision });
  const carryPhrase = personalizedPhrase || (language === "en" && pattern && pattern.length < 72
      ? englishText.noticePatternBeforeDecision.replace("{pattern}", pattern.toLowerCase())
      : daily.practice.replace(/\.$/, "."));
  return {
    title: theme,
    opening: companionTemplate.opening,
    principle: daily.principle,
    practice: daily.practice,
    question: shortQuestion,
    carryPhrase,
  };
}

function isValidView(value: string | null): value is View {
  return value === "companion" || value === "decisions" || value === "reflect" || value === "library" || value === "account";
}

function isValidHomeSection(value: string | null): value is HomeSection {
  return value === "today" || value === "ask";
}

function getInitialActiveView(): View {
  if (typeof window === "undefined") {
    return "companion";
  }

  try {
    const params = new URLSearchParams(window.location.search);
    const tabParam = params.get("tab");
    if (isValidView(tabParam)) {
      return tabParam;
    }

    const storedView = window.localStorage.getItem("aletheia-active-view");
    if (isValidView(storedView)) {
      return storedView;
    }
  } catch {
    // Fall back to the companion view when storage or URL parsing is unavailable.
  }

  return "companion";
}

function getInitialHomeSection(): HomeSection {
  if (typeof window === "undefined") {
    return "today";
  }

  try {
    const storedHomeSection = window.localStorage.getItem("aletheia-home-section");
    if (isValidHomeSection(storedHomeSection)) {
      return storedHomeSection;
    }
  } catch {
    // Fall back to the today section when storage is unavailable.
  }

  return "today";
}

