  const [counselContacts, setCounselContacts] = useState<CounselContact[]>([]);
  const [rulesOfLife, setRulesOfLife] = useState<RuleOfLife[]>([]);
  const [decisionTitle, setDecisionTitle] = useState("");
  const [decisionPressure, setDecisionPressure] = useState("");
  const [decisionEmotion, setDecisionEmotion] = useState("uncertain");
  const [focusIntentions, setFocusIntentions] = useState<string[]>([]);
  const managedAudioRef = useRef<HTMLAudioElement | null>(null);
  const managedAudioUrlRef = useRef<string | null>(null);
  const managedPlaybackRequestRef = useRef(0);
  const browserSpeechActiveRef = useRef(false);
  const [counselName, setCounselName] = useState("");
  const [counselRole, setCounselRole] = useState("mentor");
  const [counselAvatarUrl, setCounselAvatarUrl] = useState("");
  const [counselContactValue, setCounselContactValue] = useState("");
  const [counselCanViewSummaries, setCounselCanViewSummaries] = useState(true);
  const [counselCanComment, setCounselCanComment] = useState(false);
  const [counselCanReceiveCheckins, setCounselCanReceiveCheckins] = useState(false);
  const [latestCounselInvite, setLatestCounselInvite] = useState<{ name: string; url: string } | null>(null);
  const [counselInviteToken, setCounselInviteToken] = useState<string | null>(null);
  const [counselInvitePreview, setCounselInvitePreview] = useState<CounselInvitePreview | null>(null);
  const [counselInviteStatus, setCounselInviteStatus] = useState("");
  const [challengeInviteToken, setChallengeInviteToken] = useState<string | null>(null);
  const [challengeInvitePreview, setChallengeInvitePreview] = useState<ChallengeCircleSummary | null>(null);
  const [challengeInviteStatus, setChallengeInviteStatus] = useState("");
  const [challengeInviteUrl, setChallengeInviteUrl] = useState<string | null>(null);
  const [challengeCircleRefreshKey, setChallengeCircleRefreshKey] = useState(0);
  const [counselRemovalPrompt, setCounselRemovalPrompt] = useState<CounselRemovalConfirmationState | null>(null);
  const [isRemovingCounselContact, setIsRemovingCounselContact] = useState(false);
  const [currentLocalDayNumber, setCurrentLocalDayNumber] = useState<number | null>(null);
  const [currentLocalHour, setCurrentLocalHour] = useState<number | null>(null);
  const [currentLocalMonth, setCurrentLocalMonth] = useState<number | null>(null);
  const [currentLocalDayOfWeek, setCurrentLocalDayOfWeek] = useState<number | null>(null);
  
  const [counselSummaryDraft, setCounselSummaryDraftState] = useState<CounselSummaryDraft | null>(null);
  
  // Wrapper function that persists to localStorage
  const setCounselSummaryDraft = (value: CounselSummaryDraft | null) => {
    setCounselSummaryDraftState(value);
    if (typeof window !== "undefined") {
      if (value) {
        window.localStorage.setItem("aletheia-counsel-summary-draft", JSON.stringify(value));
      } else {
        window.localStorage.removeItem("aletheia-counsel-summary-draft");
      }
    }
  };
  
  const [answerFocusId, setAnswerFocusId] = useState<string | null>(null);
  const [ruleText, setRuleText] = useState("");
  const [pendingNotificationFocus, setPendingNotificationFocus] = useState(false);
  const [pendingGratitudeNotificationFocus, setPendingGratitudeNotificationFocus] = useState(false);
  const [pendingDecisionNotificationFocus, setPendingDecisionNotificationFocus] = useState<string | null>(null);
  const [pendingChallengeId, setPendingChallengeId] = useState<string | null>(null);
  const appOpenedAtRef = useRef<number>(Date.now());
  const guestQuestionCountRef = useRef(0);
  const authPromptSessionIdRef = useRef<string | null>(null);
  const authPromptActiveIdRef = useRef<string | null>(null);
  const authPromptTimeoutRef = useRef<number | null>(null);
  const refreshChallengeCircles = () => {
    setChallengeCircleRefreshKey((value) => value + 1);
  };

  useEffect(() => {
    window.setTimeout(() => {
      try {
        const saved = JSON.parse(window.localStorage.getItem(FOCUS_INTENTIONS_STORAGE_KEY) || "[]") as string[];
        if (Array.isArray(saved)) {
          setFocusIntentions(saved.filter((value) => typeof value === "string").slice(0, 3));
        }
      } catch {
        // Personalization defaults to empty when stored value is invalid.
      }
    }, 0);
  }, []);
  
  // Load translations synchronously using useMemo to ensure they're available immediately
  const translations = useMemo(() => {
    return loadTranslationsWithFallbackSync(preferences.language);
  }, [preferences.language]);
  const rawTranslations = useMemo(() => {
    return loadTranslationsSync(preferences.language);
  }, [preferences.language]);
  
  const workspaceRef = useRef<HTMLElement | null>(null);
  const bottomNavRef = useRef<HTMLDivElement | null>(null);
  const updateRefreshTimeoutRef = useRef<number | null>(null);
  const notificationFocusHandledRef = useRef(false);
  const notificationSelfHealInFlightRef = useRef(false);

  // Hydration-safe restore of client-only persisted state.
  useEffect(() => {
    let cancelled = false;
    const restoreId = window.setTimeout(() => {
      const params = new URLSearchParams(window.location.search);
      const shouldHonorNotificationFocus = params.get("source") === "notification";
      const restoredPreferences = storedPreferences();
      setStartupLanguage(restoredPreferences.language);
      setPreferences(restoredPreferences);
      setManualContext(storedManualContext());
      setThemePreference(storedThemePreference());
      setShowOnboarding(shouldShowOnboarding());
      setCarryToday(storedCarryToday(restoredPreferences));
      setScriptureMemory(storedScriptureMemory(restoredPreferences));
      setSelectedVoice(storedVoicePreference());
      setNotificationTiming(storedNotificationTiming());
      const now = new Date();
      setCurrentLocalDayNumber(Math.floor(now.getTime() / 86400000));
      setCurrentLocalHour(now.getHours());
      setCurrentLocalMonth(now.getMonth() + 1);
      setCurrentLocalDayOfWeek(now.getDay());
      setClientStateRestored(true);
      try {
        const savedPromptState = JSON.parse(window.localStorage.getItem(AUTH_PROMPT_STATE_STORAGE_KEY) || "null") as AuthPromptState | null;
        if (savedPromptState && typeof savedPromptState === "object") {
          setAuthPromptState({
            shownCount: Number(savedPromptState.shownCount) || 0,
            dismissCount: Number(savedPromptState.dismissCount) || 0,
            lastShownAt: typeof savedPromptState.lastShownAt === "string" ? savedPromptState.lastShownAt : null,
            lastShownSessionId: typeof savedPromptState.lastShownSessionId === "string" ? savedPromptState.lastShownSessionId : null,
            lastReason: savedPromptState.lastReason ?? null,
            cooldownUntil: typeof savedPromptState.cooldownUntil === "string" ? savedPromptState.cooldownUntil : null,
            recentShownAt: Array.isArray(savedPromptState.recentShownAt)
              ? savedPromptState.recentShownAt.filter((value) => typeof value === "string")
              : [],
          });
        }
      } catch {
        // Keep default prompt state if saved state is missing or invalid.
      }
      try {
        authPromptSessionIdRef.current = analyticsId(window.sessionStorage, "aletheia_session_id");
      } catch {
        authPromptSessionIdRef.current = null;
      }

      void (async () => {
        const indexedEntries = await readGratitudeEntriesFromIndexedDB();
        if (cancelled) {
          return;
        }
        if (indexedEntries && indexedEntries.length > 0) {
          setGratitudeEntries(indexedEntries);
          return;
        }

        const localEntries = storedGratitudeEntries();
        if (cancelled) {
          return;
        }
        setGratitudeEntries(localEntries);
        if (localEntries.length > 0) {
          await persistGratitudeEntries(localEntries);
        }
      })().catch(() => {
        if (!cancelled) {
          setGratitudeEntries(storedGratitudeEntries());
        }
      });

      try {
        const storedView = window.localStorage.getItem("aletheia-active-view") as View | null;
        const storedHomeSection = window.localStorage.getItem("aletheia-home-section") as HomeSection | null;
        if (!shouldHonorNotificationFocus && storedView && ["companion", "decisions", "reflect", "library", "account"].includes(storedView)) {
          setActiveViewState(storedView);
        }
        if (!shouldHonorNotificationFocus && storedHomeSection && ["today", "ask"].includes(storedHomeSection)) {
          setHomeSectionState(storedHomeSection);
        }

        // Deep link: ?tab= overrides stored view (but only when there is no notification focus)
        if (!shouldHonorNotificationFocus) {
          const tabParam = params.get("tab");
          if (tabParam && ["companion", "decisions", "reflect", "library", "account"].includes(tabParam)) {
            setActiveViewState(tabParam as View);
          }
          const challengeParam = params.get("challenge");
          if (challengeParam) {
            setPendingChallengeId(challengeParam);
          }
        }
      } catch {
        // Keep deterministic defaults if storage is unavailable.
      }
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(restoreId);
    };
  }, []);

  const translationHelpers = useMemo(() => {
    const missingTranslationToken = "__aletheia_missing_translation__";
    const resolveFallback = (key: string, fallback?: string) => fallback?.trim() ? fallback : key;
    const assertLocaleKeyExistsInDev = (key: string, fallback?: string) => {
      // Development throws loudly so we can catch missing locale coverage early.
      // Production still uses the merged English fallback by design to avoid user-facing breakage.
      if (process.env.NODE_ENV === "production" || preferences.language === "en") {
        return;
      }
      const rawValue = getTranslation(rawTranslations, key, missingTranslationToken);
      if (rawValue === missingTranslationToken) {
        console.warn(`Missing translation for ${preferences.language}.${key}. Falling back to "${fallback}".`);
      }
    };
    const t = (key: string, fallback?: string): string | string[] => {
      const resolvedFallback = resolveFallback(key, fallback);
      const result = getTranslation(translations, key, resolvedFallback);
      assertLocaleKeyExistsInDev(key, resolvedFallback);
      return result;
    };
    const ts = (key: string, fallback?: string): string => {
      const result = t(key, fallback);
      return Array.isArray(result) ? result.join(', ') : result;
    };
    return { t, ts };
  }, [preferences.language, rawTranslations, translations]);
  const { ts } = translationHelpers;
  const apiErrorKeyMap: Record<string, string> = {
    sign_in_required: "apiSignInRequired",
    rate_limited: "apiRateLimited",
    invalid_input: "apiInvalidInput",
    invalid_json: "apiInvalidInput",
    body_required: "apiInvalidInput",
    body_too_large: "apiInvalidInput",
    not_configured: "apiNotConfigured",
    unavailable: "apiUnavailable",
    not_found: "apiNotFound",
    permission_denied: "apiPermissionDenied",
    save_failed: "apiSaveFailed",
    invalid_subscription: "apiInvalidSubscription",
    confirm_delete: "apiConfirmDelete",
    invalid_image: "apiInvalidImage",
    invalid_credentials: "auth.authenticationFailed",
    authentication_failed: "auth.authenticationFailed",
    account_exists: "status.accountAlreadyExistsSignIn",
    sign_in_not_finish: "notifications.signInNotFinish",
  };
  const resolveApiErrorMessage = (error?: string | null, errorCode?: string | null, fallbackKey?: string) => {
    // Prefer structured error codes, then locale keys, and only then raw English text.
    // That keeps the app resilient in production while still localizing the visible message when possible.
    const key = errorCode ? apiErrorKeyMap[errorCode] : null;
    if (key) {
      return ts(key);
    }
    if (fallbackKey) {
      return ts(fallbackKey);
    }
    return error ?? ts('apiUnavailable');
  };

  // Build ui object from translations for backward compatibility
  const buildUiFromTranslations = (trans: TranslationData) => {
    if (!trans || Object.keys(trans).length === 0) {
      return englishText as UiText;
    }

    return trans as UiText;
  };

  const announceWorkflow = useCallback((title: string, body: string, tone: WorkflowTone = "info", action?: { label: string; onClick: () => void }) => {
    const id = crypto.randomUUID();
    setWorkflowNotice({
      id,
      title,
      body,
      tone,
      action,
    });
    return id;
  }, []);

  const updateAuthPromptState = useCallback((updater: (current: AuthPromptState) => AuthPromptState) => {
    setAuthPromptState((current) => {
      const next = updater(current);
      try {
        if (typeof window !== "undefined") {
          window.localStorage.setItem(AUTH_PROMPT_STATE_STORAGE_KEY, JSON.stringify(next));
        }
      } catch {
        // Prompt limits still work in-memory for this session.
      }
      return next;
    });
  }, []);

  const closeWorkflowNotice = useCallback((closeReason: AuthPromptCloseReason = "manual") => {
    const closingNotice = workflowNotice;
    if (!closingNotice) {
      return;
    }

    const isAuthPrompt = authPromptActiveIdRef.current === closingNotice.id;
    if (isAuthPrompt) {
      authPromptActiveIdRef.current = null;
      if (closeReason !== "cta") {
        const nextDismissCount = authPromptState.dismissCount + 1;
        const cooldownUntil = new Date(Date.now() + authPromptCooldownMs(nextDismissCount)).toISOString();
        updateAuthPromptState((current) => ({
          ...current,
          dismissCount: nextDismissCount,
          cooldownUntil,
        }));
      }
      trackClientEvent("auth_prompt_dismissed", {
        prompt_reason: authPromptState.lastReason,
        close_reason: closeReason,
        dismiss_count: authPromptState.dismissCount + (closeReason === "cta" ? 0 : 1),
      });
    }

    setWorkflowNotice(null);
  }, [authPromptState.dismissCount, authPromptState.lastReason, updateAuthPromptState, workflowNotice]);

  const maybeShowSignInPrompt = useCallback((reason: AuthPromptReason, metadata: AnalyticsMetadata = {}, options?: { bypassMinEngagement?: boolean }) => {
    if (typeof window === "undefined" || user || authStatus === "signing-in" || authStatus === "signing-out" || showOnboarding) {
      return false;
    }

    const now = Date.now();
    const promptHistory = pruneRecentPromptHistory(authPromptState.recentShownAt, now);
    const cooldownUntilMs = authPromptState.cooldownUntil ? Date.parse(authPromptState.cooldownUntil) : Number.NaN;
    const hasCooldown = Number.isFinite(cooldownUntilMs) && cooldownUntilMs > now;
    const bypassMinEngagement = options?.bypassMinEngagement ?? false;

    if (!bypassMinEngagement && now - appOpenedAtRef.current < AUTH_PROMPT_MIN_ENGAGEMENT_MS) {
      return false;
    }
    if (hasCooldown) {
      return false;
    }
    if (promptHistory.length >= AUTH_PROMPT_WEEKLY_LIMIT) {
      return false;
    }

    const sessionId = authPromptSessionIdRef.current ?? analyticsId(window.sessionStorage, "aletheia_session_id");
    authPromptSessionIdRef.current = sessionId;
    if (authPromptState.lastShownSessionId === sessionId) {
      return false;
    }

    const shownAt = new Date(now).toISOString();
    updateAuthPromptState((current) => ({
      ...current,
      shownCount: current.shownCount + 1,
      lastShownAt: shownAt,
      lastShownSessionId: sessionId,
      lastReason: reason,
      recentShownAt: [...pruneRecentPromptHistory(current.recentShownAt, now), shownAt],
    }));

    trackClientEvent("auth_prompt_shown", {
      prompt_reason: reason,
      weekly_shown_count: promptHistory.length + 1,
      ...metadata,
    });

    const promptId = announceWorkflow(
      reason === "guest_first_answer"
        ? ts('notifications.answerReadyGuestTitle')
        : ts('auth.signInForSync'),
      reason === "guest_first_answer"
        ? ts('notifications.answerReadyGuestBody')
        : ts('auth.signInSyncHistory'),
      "info",
      {
        label: ts('auth.signIn'),
        onClick: () => {
          authPromptActiveIdRef.current = null;
          trackClientEvent("auth_prompt_cta_clicked", { prompt_reason: reason, ...metadata });
          closeWorkflowNotice("cta");
          setAuthMode("login");
          openAccountFlow();
        },
      }
    );
    authPromptActiveIdRef.current = promptId;
    return true;
  }, [announceWorkflow, authPromptState.cooldownUntil, authPromptState.lastShownSessionId, authPromptState.recentShownAt, authStatus, closeWorkflowNotice, openAccountFlow, showOnboarding, ts, updateAuthPromptState, user]);

  const scheduleSignInPrompt = useCallback((reason: AuthPromptReason, metadata: AnalyticsMetadata = {}, delayMs = 2200) => {
    if (typeof window === "undefined" || user) {
      return;
    }
    if (authPromptTimeoutRef.current !== null) {
      window.clearTimeout(authPromptTimeoutRef.current);
      authPromptTimeoutRef.current = null;
    }
    authPromptTimeoutRef.current = window.setTimeout(() => {
      authPromptTimeoutRef.current = null;
      void maybeShowSignInPrompt(reason, metadata);
    }, delayMs);
  }, [maybeShowSignInPrompt, user]);

  const promptSignInForNotifications = useCallback(() => {
    trackClientEvent("gate_hit_notifications", {
      location: "account_notifications",
      has_account: Boolean(user),
    });
    void maybeShowSignInPrompt("notifications_gate", { location: "account_notifications" }, { bypassMinEngagement: true });
  }, [maybeShowSignInPrompt, user]);

  function getFriendlyAuthError(params: URLSearchParams) {
    const oauthReason = params.get("reason");
    const authError = params.get("error");

    if (oauthReason === "missing_profile") {
      return ts("auth.googleMissingProfile");
    }
    if (oauthReason === "server_error") {
      return ts("auth.googleServerError");
    }

    switch (authError) {
      case "OAuthSignin":
      case "OAuthCallbackError":
      case "CallbackRouteError":
        return ts("auth.googleSigninFailed");
      case "AccessDenied":
        return ts("auth.googleSigninCancelled");
      case "Configuration":
        return ts("auth.googleSigninUnavailable");
      default:
        return params.get("auth") === "oauth_failed"
          ? ts("auth.googleSigninDidNotFinish")
          : null;
    }
  }

  function getAuthFailureAnalytics(params: URLSearchParams): AnalyticsMetadata | null {
    const oauthReason = params.get("reason");
    const authError = params.get("error");

    if (oauthReason === "missing_profile") {
      return {
        method: "google",
        flow: "oauth_complete",
        category: "provider_failure",
        reason: "missing_profile",
      };
    }
    if (oauthReason === "server_error") {
      return {
        method: "google",
        flow: "oauth_complete",
        category: "backend_fault",
        reason: "server_error",
      };
    }

    switch (authError) {
      case "AccessDenied":
        return {
          method: "google",
          flow: "oauth_start",
          category: "canceled",
          reason: "access_denied",
        };
      case "OAuthSignin":
      case "OAuthCallbackError":
      case "CallbackRouteError":
        return {
          method: "google",
          flow: "oauth_start",
          category: "provider_failure",
          reason: authError,
        };
      case "Configuration":
        return {
          method: "google",
          flow: "oauth_start",
          category: "backend_fault",
          reason: "configuration",
        };
      default:
        return params.get("auth") === "oauth_failed"
          ? {
              method: "google",
              flow: "oauth_complete",
              category: "provider_failure",
              reason: oauthReason ?? authError ?? "oauth_failed",
            }
          : null;
    }
  }

