  async function shareWisdomPostcard(payload: WisdomPostcardPayload, placement: string) {
    try {
      const blob = await createWisdomPostcardBlob(
        {
          ...payload,
          footer: payload.footer || ts('labels.sharePrincipleNotStory'),
        },
        theme,
        preferences.language
      );
      const file = new File([blob], `aletheia-${payload.kind}-${localTodayKey()}.png`, { type: "image/png" });
      const canShareFile =
        typeof navigator !== "undefined" &&
        "share" in navigator &&
        "canShare" in navigator &&
        navigator.canShare({ files: [file] });

      if (canShareFile) {
        await navigator.share({
          title: payload.title,
          text: ts('labels.wisdomPostcardShareText'),
          files: [file],
        });
      } else {
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = file.name;
        document.body.appendChild(link);
        link.click();
        link.remove();
        URL.revokeObjectURL(url);
      }

      trackClientEvent("wisdom_postcard_shared", {
        placement,
        kind: payload.kind,
        channel: canShareFile ? "native" : "download",
        language: preferences.language,
      });
      announceWorkflow(
        canShareFile ? ts('notifications.shareSheetOpened') : ts('notifications.wisdomPostcardDownloaded'),
        ts('notifications.wisdomPostcardReadyBody'),
        "success"
      );
    } catch (error) {
      announceWorkflow(
        ts('notifications.wisdomPostcardFailed'),
        error instanceof Error ? error.message : ts('notifications.wisdomPostcardFailedBody'),
        "error"
      );
    }
  }

