function InfoHint({
  text,
  theme,
  placement = "inline",
  surface = "standard",
}: {
  text: string;
  theme: ThemeColors;
  placement?: "inline" | "corner";
  surface?: "dense" | "standard" | "hero";
}) {
  const [open, setOpen] = useState(false);
  const tooltipId = useId();
  const wrapperRef = useRef<HTMLSpanElement | null>(null);
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const tooltipRef = useRef<HTMLSpanElement | null>(null);
  const [tooltipPosition, setTooltipPosition] = useState<{ top: number; left: number; width: number }>({ top: 0, left: 12, width: 240 });
  const canUsePortal = typeof document !== "undefined";

  const positionTooltip = useCallback(() => {
    if (!buttonRef.current || !canUsePortal) {
      return;
    }
    const triggerRect = buttonRef.current.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;
    const horizontalMargin = 12;
    const preferredWidth = viewportWidth <= 390 ? 188 : 220;
    const maxWidth = Math.min(preferredWidth, Math.max(160, viewportWidth - horizontalMargin * 2));
    const tooltipHeight = tooltipRef.current?.getBoundingClientRect().height ?? 92;
    const verticalGap = 8;

    const centeredLeft = triggerRect.left + triggerRect.width / 2 - maxWidth / 2;
    const left = Math.max(horizontalMargin, Math.min(centeredLeft, viewportWidth - maxWidth - horizontalMargin));

    const hasRoomBelow = triggerRect.bottom + verticalGap + tooltipHeight <= viewportHeight - horizontalMargin;
    const top = hasRoomBelow
      ? triggerRect.bottom + verticalGap
      : Math.max(horizontalMargin, triggerRect.top - tooltipHeight - verticalGap);

    setTooltipPosition({ top, left, width: maxWidth });
  }, [canUsePortal]);

  useEffect(() => {
    if (!open) {
      return;
    }

    function closeIfOutside(event: Event) {
      const target = event.target as Node | null;
      if (target && wrapperRef.current && !wrapperRef.current.contains(target)) {
        setOpen(false);
      }
    }

    function closeOnEscape(event: globalThis.KeyboardEvent) {
      if (event.key === "Escape") {
        setOpen(false);
      }
    }

    window.addEventListener("mousedown", closeIfOutside);
    window.addEventListener("touchstart", closeIfOutside, { passive: true });
    window.addEventListener("keydown", closeOnEscape);
    window.addEventListener("resize", positionTooltip);
    window.addEventListener("scroll", positionTooltip, true);

    return () => {
      window.removeEventListener("mousedown", closeIfOutside);
      window.removeEventListener("touchstart", closeIfOutside);
      window.removeEventListener("keydown", closeOnEscape);
      window.removeEventListener("resize", positionTooltip);
      window.removeEventListener("scroll", positionTooltip, true);
    };
  }, [open, positionTooltip]);

  useLayoutEffect(() => {
    if (!open) {
      return;
    }
    positionTooltip();
    const raf = window.requestAnimationFrame(positionTooltip);
    return () => {
      window.cancelAnimationFrame(raf);
    };
  }, [open, text, positionTooltip]);

  if (!text?.trim()) {
    return null;
  }

  const tooltipBody = (
    <span
      id={tooltipId}
      ref={tooltipRef}
      role="tooltip"
      className="z-[90] rounded-lg border px-2.5 py-2 text-left text-[12px] font-normal leading-5 shadow-xl"
      style={{
        position: "fixed",
        top: tooltipPosition.top,
        left: tooltipPosition.left,
        width: tooltipPosition.width,
        borderColor: theme.borderLight,
        backgroundColor: theme.bgCardElevated,
        color: theme.textSecondary,
      }}
    >
      {text}
    </span>
  );

  const cornerWrapperClassBySurface: Record<"dense" | "standard" | "hero", string> = {
    dense: "absolute right-2 top-2 z-20 inline-flex shrink-0",
    standard: "absolute right-2.5 top-2.5 z-20 inline-flex shrink-0",
    hero: "absolute right-3 top-3 z-20 inline-flex shrink-0",
  };
  const buttonClassBySurface: Record<"dense" | "standard" | "hero", string> = {
    dense: "inline-flex items-center justify-center rounded-full border text-[7px] font-semibold leading-none transition",
    standard: "inline-flex items-center justify-center rounded-full border text-[8px] font-semibold leading-none transition",
    hero: "inline-flex items-center justify-center rounded-full border text-[8px] font-semibold leading-none transition",
  };
  const buttonSizeBySurface: Record<"dense" | "standard" | "hero", number> = {
    dense: 24,
    standard: 26,
    hero: 28,
  };
  const wrapperClassName = placement === "corner"
    ? cornerWrapperClassBySurface[surface]
    : "relative inline-flex shrink-0";
  const buttonClassName = placement === "corner"
    ? buttonClassBySurface[surface]
    : buttonClassBySurface.standard;
  const buttonSize = placement === "corner"
    ? buttonSizeBySurface[surface]
    : buttonSizeBySurface.standard;

  return (
    <span ref={wrapperRef} className={`${wrapperClassName} info-hint-anchor`}>
      <button
        ref={buttonRef}
        type="button"
        className={`${buttonClassName} info-hint-trigger cursor-help touch-manipulation`}
        style={{
          borderColor: theme.borderMedium,
          backgroundColor: theme.bgInput,
          color: theme.textSecondary,
          width: `${buttonSize}px`,
          height: `${buttonSize}px`,
          minWidth: `${buttonSize}px`,
          minHeight: `${buttonSize}px`,
          padding: 0,
          lineHeight: 1,
        }}
        aria-label={text}
        aria-expanded={open}
        aria-controls={open ? tooltipId : undefined}
        onClick={(event) => {
          event.preventDefault();
          event.stopPropagation();
          setOpen((current) => {
            const next = !current;
            if (next) {
              window.requestAnimationFrame(positionTooltip);
            }
            return next;
          });
        }}
      >
        i
      </button>
      {open ? (canUsePortal ? createPortal(tooltipBody, document.body) : tooltipBody) : null}
    </span>
  );
}

function DisclosureSection({
  title,
  summary,
  eyebrow,
  headerContent,
  sectionId,
  isOpen,
  onOpenChange,
  defaultOpen = false,
  compactCollapsed = false,
  showDetailsLabel = "Show details",
  hideDetailsLabel = "Hide details",
  className = "",
  children,
  theme,
}: {
  title: string;
  summary?: string;
  eyebrow?: string;
  headerContent?: ReactNode;
  sectionId?: string;
  isOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  defaultOpen?: boolean;
  compactCollapsed?: boolean;
  showDetailsLabel?: string;
  hideDetailsLabel?: string;
  className?: string;
  children: ReactNode;
  theme: ThemeColors;
}) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const open = isOpen ?? internalOpen;
  const setOpen = useCallback((next: boolean) => {
    if (isOpen === undefined) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  }, [isOpen, onOpenChange]);
  const useCompactClosedState = compactCollapsed && !open;

  return (
    <section id={sectionId} className={`editorial-surface min-w-0 max-w-full overflow-hidden rounded-xl border shadow-sm ${className}`} style={{ borderColor: theme.borderLight, backgroundColor: theme.bgCard }}>
      <button
        type="button"
        aria-expanded={open}
        aria-controls={sectionId ? `${sectionId}-content` : undefined}
        onClick={() => {
          const next = !open;
          setOpen(next);
          trackClientEvent("disclosure_section_toggled", {
            section: title,
            opened: next,
            eyebrow: eyebrow ?? null,
          });
        }}
        className={useCompactClosedState
          ? "group flex w-full min-w-0 flex-wrap items-start justify-between gap-2 p-2.5 text-left transition sm:p-3"
          : "group flex w-full min-w-0 flex-wrap items-start justify-between gap-2.5 p-3.5 text-left transition sm:p-4"}
        style={{ backgroundColor: open ? theme.bgCard : "transparent" }}
      >
        <span className="min-w-0 flex-1">
          {headerContent ? headerContent : (
            <>
              {eyebrow ? (
                <span className="block text-xs font-semibold uppercase tracking-[0.12em] sm:tracking-[0.16em]" style={{ color: theme.accentGold }}>{eyebrow}</span>
              ) : null}
              <span className={useCompactClosedState ? "mt-1 block text-base font-semibold" : "mt-1 block text-lg font-semibold"} style={{ color: theme.textPrimary }}>{title}</span>
              {summary ? (
                <span className={useCompactClosedState ? "mt-1 block text-sm leading-5" : "mt-1 block text-sm leading-6"} style={{ color: theme.textSecondary }}>{summary}</span>
              ) : null}
            </>
          )}
        </span>
        <span className={useCompactClosedState ? "inline-flex shrink-0 items-center gap-1 rounded-full border px-2 py-1 text-[10px] font-semibold" : "inline-flex shrink-0 items-center gap-1 rounded-full border px-2 py-1 text-[11px] font-semibold"} style={{ borderColor: theme.borderLight, backgroundColor: theme.bgInput, color: theme.textSecondary }}>
          <span>{open ? hideDetailsLabel : showDetailsLabel}</span>
          <ChevronDown size={12} style={{ transform: open ? "rotate(180deg)" : "rotate(0deg)", transition: "transform 180ms ease" }} />
        </span>
      </button>
      {open ? (
        <div id={sectionId ? `${sectionId}-content` : undefined} className="min-w-0 max-w-full overflow-x-clip border-t p-3.5 sm:p-4" style={{ borderColor: theme.borderLight }}>
          {children}
        </div>
      ) : null}
    </section>
  );
}

